===== src/atoi.rs =====
     1	//! C `atoi` semantics.
     2	//!
     3	//! `std::atoi(s)` is specified as `(int)strtol(s, nullptr, 10)` with undefined
     4	//! behaviour on overflow. glibc's `strtol` saturates at `LONG_MAX`/`LONG_MIN`
     5	//! and the narrowing cast to `int` keeps the low 32 bits, which is what the
     6	//! reference binary does; we reproduce that exactly.
     7	
     8	/// Parse a string the way C's `atoi` does: skip leading whitespace, accept an
     9	/// optional sign, consume decimal digits, and stop at the first character that
    10	/// is not a digit. Anything unparseable yields `0`.
    11	pub fn atoi(s: &str) -> i32 {
    12	    let b = s.as_bytes();
    13	    let mut i = 0usize;
    14	
    15	    // isspace(): space, \t, \n, \v, \f, \r
    16	    while i < b.len() && (b[i] == b' ' || (0x09..=0x0d).contains(&b[i])) {
    17	        i += 1;
    18	    }
    19	
    20	    let mut negative = false;
    21	    if i < b.len() && (b[i] == b'+' || b[i] == b'-') {
    22	        negative = b[i] == b'-';
    23	        i += 1;
    24	    }
    25	
    26	    let mut acc: i64 = 0;
    27	    let mut overflowed = false;
    28	    while i < b.len() && b[i].is_ascii_digit() {
    29	        if !overflowed {
    30	            let digit = i64::from(b[i] - b'0');
    31	            match acc.checked_mul(10).and_then(|v| v.checked_add(digit)) {
    32	                Some(v) => acc = v,
    33	                None => overflowed = true,
    34	            }
    35	        }
    36	        i += 1;
    37	    }
    38	
    39	    let wide = if overflowed {
    40	        if negative {
    41	            i64::MIN
    42	        } else {
    43	            i64::MAX
    44	        }
    45	    } else if negative {
    46	        -acc
    47	    } else {
    48	        acc
    49	    };
    50	
    51	    wide as i32
    52	}
    53	
    54	#[cfg(test)]
    55	mod tests {
    56	    use super::atoi;
    57	
    58	    #[test]
    59	    fn matches_c_semantics() {
    60	        assert_eq!(atoi("19"), 19);
    61	        assert_eq!(atoi(""), 0);
    62	        assert_eq!(atoi("abc"), 0);
    63	        assert_eq!(atoi("12abc"), 12);
    64	        assert_eq!(atoi(" 5"), 5);
    65	        assert_eq!(atoi("+3"), 3);
    66	        assert_eq!(atoi("-5"), -5);
    67	        assert_eq!(atoi("3.9"), 3);
    68	        assert_eq!(atoi("0x5"), 0);
    69	        assert_eq!(atoi("007"), 7);
    70	        // glibc saturates to LONG_MAX, then truncates to int.
    71	        assert_eq!(atoi("999999999999999999999"), -1);
    72	    }
    73	}
===== src/shape.rs =====
     1	//! The polygon `test19` triangulates: a damped sine "fractal" edge closed off
     2	//! along the x-axis.
     3	//!
     4	//! The ring is deliberately self-intersecting, which is what drives earcut
     5	//! into its recovery passes.
     6	
     7	/// Build the ring for a given `n`, matching the C++ loop exactly:
     8	///
     9	/// ```text
    10	/// for (int i = 0; i < n * 2; i++) {
    11	///     double t = double(i) / (n * 2);
    12	///     double x = t * 3.0;
    13	///     double y = std::sin(t * 10.0) * std::exp(-t) * 2.0 + 1.0;
    14	///     fractal.push_back({x, y});
    15	/// }
    16	/// fractal.push_back({3.0, 0.0});
    17	/// fractal.push_back({0.0, 0.0});
    18	/// ```
    19	///
    20	/// `n * 2` is `int` arithmetic in C++, so it is reproduced with wrapping
    21	/// 32-bit multiplication here. A non-positive count simply skips the loop and
    22	/// leaves the two closing points.
    23	pub fn fractal_ring(n: i32) -> Vec<[f64; 2]> {
    24	    let count = n.wrapping_mul(2);
    25	
    26	    let mut fractal: Vec<[f64; 2]> = Vec::new();
    27	    let mut i: i32 = 0;
    28	    while i < count {
    29	        let t = f64::from(i) / f64::from(count);
    30	        let x = t * 3.0;
    31	        let y = (t * 10.0).sin() * (-t).exp() * 2.0 + 1.0;
    32	        fractal.push([x, y]);
    33	        i += 1;
    34	    }
    35	
    36	    fractal.push([3.0, 0.0]);
    37	    fractal.push([0.0, 0.0]);
    38	
    39	    fractal
    40	}
    41	
    42	#[cfg(test)]
    43	mod tests {
    44	    use super::fractal_ring;
    45	
    46	    #[test]
    47	    fn closing_points_always_present() {
    48	        assert_eq!(fractal_ring(0), vec![[3.0, 0.0], [0.0, 0.0]]);
    49	        assert_eq!(fractal_ring(-7), vec![[3.0, 0.0], [0.0, 0.0]]);
    50	        assert_eq!(fractal_ring(3).len(), 8);
    51	    }
    52	}
