===== src/earcut/geom.rs =====
     1	//! Scalar helpers used throughout the triangulator.
     2	//!
     3	//! These mirror the free-standing arithmetic of the C++ header exactly,
     4	//! including comparison operators — the ear test is sign-sensitive, so `>=`
     5	//! versus `>` changes the emitted triangulation.
     6	
     7	/// `(0 < val) - (val < 0)`, the C++ `sign` helper.
     8	#[inline]
     9	pub fn sign(val: f64) -> i32 {
    10	    i32::from(0.0 < val) - i32::from(val < 0.0)
    11	}
    12	
    13	/// `std::min<double>` — returns `b` only when `b < a`, matching C++ ordering
    14	/// semantics (and therefore its NaN behaviour) rather than `f64::min`.
    15	#[inline]
    16	pub fn fmin(a: f64, b: f64) -> f64 {
    17	    if b < a {
    18	        b
    19	    } else {
    20	        a
    21	    }
    22	}
    23	
    24	/// `std::max<double>` — returns `b` only when `a < b`.
    25	#[inline]
    26	pub fn fmax(a: f64, b: f64) -> f64 {
    27	    if a < b {
    28	        b
    29	    } else {
    30	        a
    31	    }
    32	}
    33	
    34	/// Signed area of the triangle `p q r`, doubled. Negative means convex under
    35	/// earcut's winding convention.
    36	#[inline]
    37	pub fn area_xy(px: f64, py: f64, qx: f64, qy: f64, rx: f64, ry: f64) -> f64 {
    38	    (qy - py) * (rx - qx) - (qx - px) * (ry - qy)
    39	}
    40	
    41	/// Is `p` inside (or on the boundary of) triangle `a b c`?
    42	#[inline]
    43	#[allow(clippy::too_many_arguments)]
    44	pub fn point_in_triangle(
    45	    ax: f64,
    46	    ay: f64,
    47	    bx: f64,
    48	    by: f64,
    49	    cx: f64,
    50	    cy: f64,
    51	    px: f64,
    52	    py: f64,
    53	) -> bool {
    54	    (cx - px) * (ay - py) - (ax - px) * (cy - py) >= 0.0
    55	        && (ax - px) * (by - py) - (bx - px) * (ay - py) >= 0.0
    56	        && (bx - px) * (cy - py) - (cx - px) * (by - py) >= 0.0
    57	}

===== src/earcut/predicates.rs =====
     1	//! Node-level geometric predicates — the C++ member functions that take
     2	//! `Node*` arguments.
     3	
     4	use super::geom::{area_xy, fmax, fmin, sign};
     5	use super::Earcut;
     6	
     7	impl Earcut {
     8	    /// Doubled signed area of the triangle `p q r`.
     9	    #[inline]
    10	    pub fn area(&self, p: usize, q: usize, r: usize) -> f64 {
    11	        let n = &self.nodes;
    12	        area_xy(n[p].x, n[p].y, n[q].x, n[q].y, n[r].x, n[r].y)
    13	    }
    14	
    15	    /// Exact coordinate equality (not an epsilon comparison — earcut relies on
    16	    /// bit equality here).
    17	    #[inline]
    18	    pub fn equals(&self, p1: usize, p2: usize) -> bool {
    19	        self.nodes[p1].x == self.nodes[p2].x && self.nodes[p1].y == self.nodes[p2].y
    20	    }
    21	
    22	    /// Do segments `p1q1` and `p2q2` intersect, including collinear touching?
    23	    pub fn intersects(&self, p1: usize, q1: usize, p2: usize, q2: usize) -> bool {
    24	        let o1 = sign(self.area(p1, q1, p2));
    25	        let o2 = sign(self.area(p1, q1, q2));
    26	        let o3 = sign(self.area(p2, q2, p1));
    27	        let o4 = sign(self.area(p2, q2, q1));
    28	
    29	        if o1 != o2 && o3 != o4 {
    30	            return true; // general case
    31	        }
    32	
    33	        // Collinear special cases.
    34	        if o1 == 0 && self.on_segment(p1, p2, q1) {
    35	            return true;
    36	        }
    37	        if o2 == 0 && self.on_segment(p1, q2, q1) {
    38	            return true;
    39	        }
    40	        if o3 == 0 && self.on_segment(p2, p1, q2) {
    41	            return true;
    42	        }
    43	        if o4 == 0 && self.on_segment(p2, q1, q2) {
    44	            return true;
    45	        }
    46	
    47	        false
    48	    }
    49	
    50	    /// For collinear `p`, `q`, `r`: does `q` lie within the bounding box of
    51	    /// segment `pr`?
    52	    pub fn on_segment(&self, p: usize, q: usize, r: usize) -> bool {
    53	        let n = &self.nodes;
    54	        n[q].x <= fmax(n[p].x, n[r].x)
    55	            && n[q].x >= fmin(n[p].x, n[r].x)
    56	            && n[q].y <= fmax(n[p].y, n[r].y)
    57	            && n[q].y >= fmin(n[p].y, n[r].y)
