    91	    /// Does the midpoint of `ab` fall inside the polygon? (Even-odd ray cast.)
    92	    pub fn middle_inside(&self, a: usize, b: usize) -> bool {
    93	        let mut inside = false;
    94	        let px = (self.nodes[a].x + self.nodes[b].x) / 2.0;
    95	        let py = (self.nodes[a].y + self.nodes[b].y) / 2.0;
    96	
    97	        let mut p = a;
    98	        loop {
    99	            let pn = self.nodes[p].next;
   100	            let (pxx, pyy) = (self.nodes[p].x, self.nodes[p].y);
   101	            let (nxx, nyy) = (self.nodes[pn].x, self.nodes[pn].y);
   102	            if ((pyy > py) != (nyy > py))
   103	                && nyy != pyy
   104	                && (px < (nxx - pxx) * (py - pyy) / (nyy - pyy) + pxx)
   105	            {
   106	                inside = !inside;
   107	            }
   108	            p = pn;
   109	            if p == a {
   110	                return inside;
   111	            }
   112	        }
   113	    }
