   115	    /// Can `ab` be used to split the polygon in two?
   116	    pub fn is_valid_diagonal(&self, a: usize, b: usize) -> bool {
   117	        let an = self.nodes[a].next;
   118	        let ap = self.nodes[a].prev;
   119	        let bn = self.nodes[b].next;
   120	        let bp = self.nodes[b].prev;
   121	
   122	        self.nodes[an].i != self.nodes[b].i
   123	            && self.nodes[ap].i != self.nodes[b].i
   124	            // doesn't intersect other edges
   125	            && !self.intersects_polygon(a, b)
   126	            && ((self.locally_inside(a, b)
   127	                && self.locally_inside(b, a)
   128	                && self.middle_inside(a, b)
   129	                // does not create opposite-facing sectors
   130	                && (self.area(ap, a, bp) != 0.0 || self.area(a, bp, b) != 0.0))
   131	                // special zero-length case
   132	                || (self.equals(a, b)
   133	                    && self.area(ap, a, an) > 0.0
   134	                    && self.area(bp, b, bn) > 0.0))
   135	    }
