 91	    /// Drop duplicate and collinear vertices between `start` and `end`.
 92	    pub fn filter_points(&mut self, start: usize, end_in: usize) -> usize {
 93	        if start == NULL {
 94	            return NULL;
 95	        }
 96	        let mut end = if end_in == NULL { start } else { end_in };
 97	
 98	        let mut p = start;
 99	        loop {
100	            let mut again = false;
101	
102	            let next = self.nodes[p].next;
103	            let prev = self.nodes[p].prev;
104	            if !self.nodes[p].steiner && (self.equals(p, next) || self.area(prev, p, next) == 0.0) {
105	                self.remove_node(p);
106	                p = self.nodes[p].prev;
107	                end = p;
108	
109	                if p == self.nodes[p].next {
110	                    break;
111	                }
112	                again = true;
113	            } else {
114	                p = next;
115	            }
116	
117	            if !again && p == end {
118	                break;
119	            }
120	        }
121	
122	        end
123	    }
