125	    /// Main ear-slicing loop.
126	    pub fn earcut_linked(&mut self, ear_in: usize, pass: i32) {
127	        let mut ear = ear_in;
128	        if ear == NULL {
129	            return;
130	        }
131	
132	        // Interlink polygon nodes in z-order.
133	        if pass == 0 && self.hashing {
134	            self.index_curve(ear);
135	        }
136	
137	        let mut stop = ear;
138	
139	        while self.nodes[ear].prev != self.nodes[ear].next {
140	            let prev = self.nodes[ear].prev;
141	            let next = self.nodes[ear].next;
142	
143	            let is_ear = if self.hashing {
144	                self.is_ear_hashed(ear)
145	            } else {
146	                self.is_ear(ear)
147	            };
148	
149	            if is_ear {
150	                // Cut off the triangle.
151	                self.indices.push(self.nodes[prev].i);
152	                self.indices.push(self.nodes[ear].i);
153	                self.indices.push(self.nodes[next].i);
154	
155	                self.remove_node(ear);
156	
157	                // Skipping the next vertex leads to fewer sliver triangles.
158	                ear = self.nodes[next].next;
159	                stop = self.nodes[next].next;
160	
161	                continue;
162	            }
163	
164	            ear = next;
165	
166	            // Looped through the whole remaining polygon without finding an ear.
167	            if ear == stop {
168	                if pass == 0 {
169	                    // Try filtering points and slicing again.
170	                    let filtered = self.filter_points(ear, NULL);
171	                    self.earcut_linked(filtered, 1);
172	                } else if pass == 1 {
173	                    // Try curing all small self-intersections locally.
174	                    let filtered = self.filter_points(ear, NULL);
175	                    let cured = self.cure_local_intersections(filtered);
176	                    self.earcut_linked(cured, 2);
177	                } else if pass == 2 {
178	                    // Last resort: split the remaining polygon in two.
179	                    self.split_earcut(ear);
180	                }
181	                break;
182	            }
183	        }
184	    }
