186	    /// Ear test used while the z-order hash is off.
187	    pub fn is_ear(&self, ear: usize) -> bool {
188	        let a = self.nodes[ear].prev;
189	        let b = ear;
190	        let c = self.nodes[ear].next;
191	
192	        if self.area(a, b, c) >= 0.0 {
193	            return false; // reflex, can't be an ear
194	        }
195	
196	        let (ax, ay) = (self.nodes[a].x, self.nodes[a].y);
197	        let (bx, by) = (self.nodes[b].x, self.nodes[b].y);
198	        let (cx, cy) = (self.nodes[c].x, self.nodes[c].y);
199	
200	        // Make sure no other point lies inside the candidate ear.
201	        let ear_prev = self.nodes[ear].prev;
202	        let mut p = self.nodes[self.nodes[ear].next].next;
203	        while p != ear_prev {
204	            if point_in_triangle(ax, ay, bx, by, cx, cy, self.nodes[p].x, self.nodes[p].y)
205	                && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
206	            {
207	                return false;
208	            }
209	            p = self.nodes[p].next;
210	        }
211	
212	        true
213	    }
