    for (k, &i) in idx.iter().enumerate() {
        if (i as usize) >= total {
            bad.push(format!("index[{}] = {} >= total verts {}", k, i, total));
            break;
        }
    }
    println!(
        "OK case={} verts={} tris={} bad={:?}",
        name,
        total,
        idx.len() / 3,
        bad
    );
    if !bad.is_empty() {
        std::process::exit(3);
    }
}

