use earcut_test19::earcut::earcut;

struct Rng(u64);
impl Rng {
    fn next(&mut self) -> u64 {
        let mut x = self.0;
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        self.0 = x;
        x
    }
    fn below(&mut self, n: u64) -> u64 { self.next() % n }
}

fn coord(r: &mut Rng, mode: u64) -> f64 {
    match mode {
        0 => (r.below(7) as f64) - 3.0,
        1 => (r.below(3) as f64),
        2 => {
            let pool = [0.0f64, -0.0, 1.0, -1.0, 1e308, -1e308, f64::MAX, -f64::MAX,
                        f64::MIN_POSITIVE, 5e-324, f64::INFINITY, f64::NEG_INFINITY, f64::NAN];
            pool[(r.below(pool.len() as u64)) as usize]
        }
        3 => {
            let pool = [0.0f64, -0.0, 1.0, -1.0, 2.0, 1e300, -1e300, 1e-300];
            pool[(r.below(pool.len() as u64)) as usize]
        }
        _ => f64::from_bits(r.next()),
    }
}

fn main() {
    let a: Vec<String> = std::env::args().collect();
    let seed: u64 = a.get(1).and_then(|s| s.parse().ok()).unwrap_or(1);
    let iters: u64 = a.get(2).and_then(|s| s.parse().ok()).unwrap_or(2000);
