// Second battery: API misuse, reuse, area conservation, deep recursion.
use earcut_test19::earcut::node::NULL;
use earcut_test19::earcut::{earcut, Earcut};

fn ring(p: &[(f64, f64)]) -> Vec<[f64; 2]> {
    p.iter().map(|&(x, y)| [x, y]).collect()
}
fn circle(n: usize, r: f64, cx: f64, cy: f64, ccw: bool) -> Vec<[f64; 2]> {
    (0..n)
        .map(|k| {
            let a = 2.0 * std::f64::consts::PI * (k as f64) / (n as f64);
            let a = if ccw { a } else { -a };
            [cx + r * a.cos(), cy + r * a.sin()]
        })
        .collect()
}
fn shoelace(r: &[[f64; 2]]) -> f64 {
    let mut s = 0.0;
    for i in 0..r.len() {
        let j = (i + 1) % r.len();
        s += r[i][0] * r[j][1] - r[j][0] * r[i][1];
    }
    s / 2.0
}

fn tri_area_sum(poly: &[Vec<[f64; 2]>], idx: &[u32]) -> f64 {
    let flat: Vec<[f64; 2]> = poly.iter().flatten().copied().collect();
    let mut s = 0.0;
    for t in idx.chunks(3) {
        let (a, b, c) = (flat[t[0] as usize], flat[t[1] as usize], flat[t[2] as usize]);
        s += ((b[0] - a[0]) * (c[1] - a[1]) - (c[0] - a[0]) * (b[1] - a[1])).abs() / 2.0;
    }
    s
}

struct Rng(u64);
impl Rng {
    fn f(&mut self) -> f64 {
        let mut x = self.0;
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        self.0 = x;
        ((x >> 11) as f64) / ((1u64 << 53) as f64)
    }
}

fn main() {
    let a: Vec<String> = std::env::args().collect();
    let which = a.get(1).map(|s| s.as_str()).unwrap_or("all");

    if which == "reuse" {
        // Earcut instance reused across runs, incl. after an early return.
        let mut e = Earcut::new();
        e.run(&[]); // early return, arena never cleared
        e.run(&[ring(&[(0.0, 0.0), (1.0, 0.0)])]); // early return #2
        e.run(&[ring(&[(0.0, 0.0), (4.0, 0.0), (4.0, 4.0), (0.0, 4.0)])]);
        println!("reuse pass1 {:?} arena={}", e.indices, e.nodes.len());
        e.run(&[
            ring(&[(0.0, 0.0), (4.0, 0.0), (4.0, 4.0), (0.0, 4.0)]),
            ring(&[(1.0, 1.0), (1.0, 3.0), (3.0, 3.0), (3.0, 1.0)]),
        ]);
        println!("reuse pass2 {:?} arena={}", e.indices, e.nodes.len());
        // same instance, third run after a run that DID clear
        e.run(&[circle(90, 1.0, 0.0, 0.0, true)]);
        println!("reuse pass3 tris={} arena={}", e.indices.len() / 3, e.nodes.len());
        return;
    }

    if which == "sortlinked-null" {
        let mut e = Earcut::new();
        let r = e.sort_linked(NULL);
        println!("sort_linked(NULL) = {}", r);
        return;
    }
    if which == "filterpoints-null" {
        let mut e = Earcut::new();
        println!("filter_points(NULL,NULL) = {}", e.filter_points(NULL, NULL));
        println!("cure(NULL) = {}", e.cure_local_intersections(NULL));
        e.earcut_linked(NULL, 0);
        println!("earcut_linked(NULL) ok");
        return;
    }
    if which == "zorder-nan" {
        let e = Earcut::new();
        println!(
            "z_order(NaN,NaN)={} z_order(inf,inf)={} z_order(-inf,3)={} z_order(1e300,1e300)={}",
            e.z_order(f64::NAN, f64::NAN),
            e.z_order(f64::INFINITY, f64::INFINITY),
            e.z_order(f64::NEG_INFINITY, 3.0),
            e.z_order(1e300, 1e300)
        );
        return;
    }

    if which == "area" {
        // area conservation on well-formed inputs (incl. holes / steiner)
        let checks: Vec<(&str, Vec<Vec<[f64; 2]>>, f64)> = vec![
            (
                "square+square hole",
                vec![
                    ring(&[(0.0, 0.0), (4.0, 0.0), (4.0, 4.0), (0.0, 4.0)]),
                    ring(&[(1.0, 1.0), (1.0, 3.0), (3.0, 3.0), (3.0, 1.0)]),
                ],
                12.0,
            ),
            (
                "square+wrong-wound hole",
                vec![
                    ring(&[(0.0, 0.0), (4.0, 0.0), (4.0, 4.0), (0.0, 4.0)]),
                    ring(&[(1.0, 1.0), (3.0, 1.0), (3.0, 3.0), (1.0, 3.0)]),
                ],
                12.0,
            ),
            (
                "circle+3 holes",
                vec![
                    circle(40, 10.0, 0.0, 0.0, true),
                    circle(9, 2.0, -5.0, 0.0, false),
                    circle(9, 2.0, 5.0, 0.0, false),
                    circle(9, 2.0, 0.0, 5.0, false),
                ],
                shoelace(&circle(40, 10.0, 0.0, 0.0, true)).abs()
                    - 3.0 * shoelace(&circle(9, 2.0, 0.0, 0.0, false)).abs(),
            ),
            (
                "big circle 500",
                vec![circle(500, 7.0, 1.0, 2.0, true)],
                shoelace(&circle(500, 7.0, 1.0, 2.0, true)).abs(),
            ),
            (
                "square+steiner",
                vec![
                    ring(&[(0.0, 0.0), (4.0, 0.0), (4.0, 4.0), (0.0, 4.0)]),
                    ring(&[(2.0, 2.0)]),
                ],
                16.0,
            ),
            (
                "square+5 steiner",
                vec![
                    ring(&[(0.0, 0.0), (4.0, 0.0), (4.0, 4.0), (0.0, 4.0)]),
                    ring(&[(1.0, 1.0)]),
                    ring(&[(3.0, 1.0)]),
                    ring(&[(2.0, 2.0)]),
                    ring(&[(1.0, 3.0)]),
                    ring(&[(3.0, 3.0)]),
                ],
                16.0,
            ),
            (
                "hashed square+hole (>80 verts)",
                vec![
                    {
                        let mut v = Vec::new();
                        for i in 0..25 { v.push([i as f64 * 0.4, 0.0]); }
                        for i in 0..25 { v.push([10.0, i as f64 * 0.4]); }
                        for i in 0..25 { v.push([10.0 - i as f64 * 0.4, 10.0]); }
                        for i in 0..25 { v.push([0.0, 10.0 - i as f64 * 0.4]); }
                        v
                    },
                    circle(20, 2.0, 5.0, 5.0, false),
                ],
                100.0 - shoelace(&circle(20, 2.0, 5.0, 5.0, false)).abs(),
            ),
        ];
        let mut fails = 0;
        for (name, poly, expect) in checks {
            let idx = earcut(&poly);
            let got = tri_area_sum(&poly, &idx);
            let rel = (got - expect).abs() / expect.abs().max(1e-12);
            let verdict = if rel < 1e-9 { "ok" } else { fails += 1; "MISMATCH" };
            println!("{:<34} tris={:<4} area={:.10} expect={:.10} {}", name, idx.len()/3, got, expect, verdict);
        }
        std::process::exit(if fails > 0 { 3 } else { 0 });
    }

    if which == "deep" {
        // random self-intersecting ring: maximal splitEarcut pressure
        let n: usize = a.get(2).and_then(|s| s.parse().ok()).unwrap_or(2000);
        let seed: u64 = a.get(3).and_then(|s| s.parse().ok()).unwrap_or(12345);
        let mut r = Rng(seed | 1);
        let poly = vec![(0..n).map(|_| [r.f() * 100.0, r.f() * 100.0]).collect::<Vec<_>>()];
        let idx = earcut(&poly);
        for &i in &idx {
            assert!((i as usize) < n, "oob index");
        }
        println!("deep n={} seed={} tris={}", n, seed, idx.len() / 3);
        return;
    }

    if which == "nan-holes" {
        // several holes whose leftmost x is NaN -> comparator is not a total order
        let mut poly = vec![ring(&[(0.0, 0.0), (10.0, 0.0), (10.0, 10.0), (0.0, 10.0)])];
        for k in 0..12 {
            let f = k as f64;
            poly.push(ring(&[
                (f64::NAN, 1.0 + f * 0.5),
                (1.0 + f * 0.3, 1.0 + f * 0.5),
                (1.0 + f * 0.3, 1.4 + f * 0.5),
            ]));
        }
        let total: usize = poly.iter().map(|r| r.len()).sum();
        let idx = earcut(&poly);
        for &i in &idx {
            assert!((i as usize) < total, "oob index {}", i);
        }
        println!("nan-holes tris={}", idx.len() / 3);
        return;
    }

    if which == "many-empty-rings" {
        let mut poly = vec![ring(&[(0.0, 0.0), (4.0, 0.0), (4.0, 4.0), (0.0, 4.0)])];
        for _ in 0..100000 {
            poly.push(vec![]);
        }
        let idx = earcut(&poly);
        println!("many-empty-rings tris={}", idx.len() / 3);
        return;
    }

    eprintln!("usage: case2 <reuse|sortlinked-null|filterpoints-null|zorder-nan|area|deep|nan-holes|many-empty-rings>");
    std::process::exit(2);
}

