// Randomised area-conservation + validity check for well-formed hole/Steiner input.
use earcut_test19::earcut::earcut;

struct Rng(u64);
impl Rng {
    fn n(&mut self) -> u64 { let mut x=self.0; x^=x<<13; x^=x>>7; x^=x<<17; self.0=x; x }
    fn f(&mut self) -> f64 { ((self.n()>>11) as f64)/((1u64<<53) as f64) }
    fn r(&mut self, n: u64) -> u64 { self.n()%n }
}

fn circle(n: usize, rad: f64, cx: f64, cy: f64, ccw: bool) -> Vec<[f64;2]> {
    (0..n).map(|k| { let a = 2.0*std::f64::consts::PI*(k as f64)/(n as f64);
        let a = if ccw {a} else {-a}; [cx+rad*a.cos(), cy+rad*a.sin()] }).collect()
}
fn shoelace(r: &[[f64;2]]) -> f64 { let mut s=0.0; for i in 0..r.len() { let j=(i+1)%r.len(); s += r[i][0]*r[j][1]-r[j][0]*r[i][1]; } s/2.0 }

fn main() {
    let a: Vec<String> = std::env::args().collect();
    let seed: u64 = a.get(1).and_then(|s|s.parse().ok()).unwrap_or(1);
    let iters: u64 = a.get(2).and_then(|s|s.parse().ok()).unwrap_or(500);
    let mut rng = Rng(seed|1);
    let mut worst = 0.0f64;
    for it in 0..iters {
        let outer_n = 3 + rng.r(120) as usize;
        let outer_r = 100.0;
        let outer = circle(outer_n, outer_r, 0.0, 0.0, true);
        let mut poly = vec![outer.clone()];
        let mut expect = shoelace(&outer).abs();
        // holes on a coarse grid so they never overlap
        let nh = rng.r(10);
        let mut used = std::collections::HashSet::new();
        for _ in 0..nh {
            let gx = rng.r(7) as i64 - 3;
            let gy = rng.r(7) as i64 - 3;
            if !used.insert((gx,gy)) { continue; }
            let hn = 3 + rng.r(10) as usize;
            let hr = 2.0 + rng.f()*6.0;
            let h = circle(hn, hr, gx as f64*18.0, gy as f64*18.0, false);
            expect -= shoelace(&h).abs();
            poly.push(h);
        }
        // steiner points, on a disjoint grid
        let ns = rng.r(6);
        for _ in 0..ns {
            let x = (rng.r(9) as f64 - 4.0)*18.0 + 9.0;
            let y = (rng.r(9) as f64 - 4.0)*18.0 + 9.0;
            if x*x + y*y < (outer_r*0.6)*(outer_r*0.6) { poly.push(vec![[x,y]]); }
        }
        let total: usize = poly.iter().map(|r|r.len()).sum();
        let flat: Vec<[f64;2]> = poly.iter().flatten().copied().collect();
        let idx = earcut(&poly);
        if idx.len()%3 != 0 { println!("BAD it={} not multiple of 3", it); std::process::exit(3); }
        let mut area = 0.0;
        for t in idx.chunks(3) {
            for &i in t { if (i as usize) >= total { println!("BAD it={} oob {}", it, i); std::process::exit(3); } }
            let (p,q,r2)=(flat[t[0] as usize], flat[t[1] as usize], flat[t[2] as usize]);
            area += ((q[0]-p[0])*(r2[1]-p[1])-(r2[0]-p[0])*(q[1]-p[1])).abs()/2.0;
        }
        let rel = (area-expect).abs()/expect.abs().max(1e-12);
        if rel > worst { worst = rel; }
        if rel > 1e-9 {
            println!("BAD it={} seed={} area={} expect={} rel={} rings={:?}", it, seed, area, expect, rel,
                poly.iter().map(|r|r.len()).collect::<Vec<_>>());
            std::process::exit(3);
        }
    }
    println!("fuzz2 ok seed={} iters={} worst_rel_area_err={:.3e}", seed, iters, worst);
}
