// Well-formed random input only: holes + steiner strictly inside, no duplicates.
use earcut_test19::earcut::earcut;
use std::collections::HashSet;
struct Rng(u64);
impl Rng { fn n(&mut self)->u64{let mut x=self.0;x^=x<<13;x^=x>>7;x^=x<<17;self.0=x;x}
    fn f(&mut self)->f64{((self.n()>>11) as f64)/((1u64<<53) as f64)} fn r(&mut self,n:u64)->u64{self.n()%n} }
fn circle(n:usize,rad:f64,cx:f64,cy:f64,ccw:bool)->Vec<[f64;2]>{(0..n).map(|k|{let a=2.0*std::f64::consts::PI*(k as f64)/(n as f64);let a=if ccw{a}else{-a};[cx+rad*a.cos(),cy+rad*a.sin()]}).collect()}
fn shoelace(r:&[[f64;2]])->f64{let mut s=0.0;for i in 0..r.len(){let j=(i+1)%r.len();s+=r[i][0]*r[j][1]-r[j][0]*r[i][1];}s/2.0}
fn main(){
    let a:Vec<String>=std::env::args().collect();
    let seed:u64=a.get(1).and_then(|s|s.parse().ok()).unwrap_or(1);
    let iters:u64=a.get(2).and_then(|s|s.parse().ok()).unwrap_or(500);
    let mut rng=Rng(seed|1); let mut worst=(0.0f64,String::new());
    for it in 0..iters {
        let outer_n=3+rng.r(120) as usize; let rad=100.0;
        let inr=rad*(std::f64::consts::PI/outer_n as f64).cos();
        let outer=circle(outer_n,rad,0.0,0.0,true);
        let mut poly=vec![outer.clone()]; let mut expect=shoelace(&outer).abs();
        let mut occupied:HashSet<(i64,i64)>=HashSet::new();
        let cell=18.0f64;
        for _ in 0..rng.r(10) {
            let gx=rng.r(7) as i64-3; let gy=rng.r(7) as i64-3;
            if !occupied.insert((gx,gy)){continue;}
            let (cx,cy)=(gx as f64*cell, gy as f64*cell);
            let hr=2.0+rng.f()*6.0;
            if (cx*cx+cy*cy).sqrt()+hr > inr*0.95 {continue;}
            let h=circle(3+rng.r(10) as usize,hr,cx,cy,false);
            expect-=shoelace(&h).abs(); poly.push(h);
        }
        let mut spts:HashSet<(u64,u64)>=HashSet::new();
        for _ in 0..rng.r(6) {
            let gx=rng.r(9) as i64-4; let gy=rng.r(9) as i64-4;
            if occupied.contains(&(gx,gy)) || occupied.contains(&(gx+1,gy)) || occupied.contains(&(gx,gy+1)) || occupied.contains(&(gx+1,gy+1)) {continue;}
            let (x,y)=(gx as f64*cell+cell/2.0, gy as f64*cell+cell/2.0);
            if (x*x+y*y).sqrt()>inr*0.9 {continue;}
            if !spts.insert((x.to_bits(),y.to_bits())){continue;}
            poly.push(vec![[x,y]]);
        }
        let total:usize=poly.iter().map(|r|r.len()).sum();
        let flat:Vec<[f64;2]>=poly.iter().flatten().copied().collect();
        let idx=earcut(&poly);
        if idx.len()%3!=0 {println!("BAD it={} idxlen",it);std::process::exit(3);}
        let mut area=0.0;
        for t in idx.chunks(3){ for &i in t{ if (i as usize)>=total {println!("BAD it={} oob",it);std::process::exit(3);} }
            let(p,q,r)=(flat[t[0] as usize],flat[t[1] as usize],flat[t[2] as usize]);
            area+=((q[0]-p[0])*(r[1]-p[1])-(r[0]-p[0])*(q[1]-p[1])).abs()/2.0; }
        let rel=(area-expect).abs()/expect.abs();
        if rel>worst.0 {worst=(rel,format!("it={} rings={:?}",it,poly.iter().map(|r|r.len()).collect::<Vec<_>>()));}
        if rel>1e-9 { println!("BAD seed={} it={} area={} expect={} rel={:.3e} rings={:?}",seed,it,area,expect,rel,poly.iter().map(|r|r.len()).collect::<Vec<_>>()); std::process::exit(3); }
    }
    println!("fuzz3 ok seed={} iters={} worst={:.3e} {}",seed,iters,worst.0,worst.1);
}
